<div class="card"><h3>On-page recommendations</h3><p class="small">Generate suggestions with your configured AI provider, or write and save your own. Publishing to your website is a separate, manual action.</p><?php $pageChoices=[];foreach($records as $record)$pageChoices[$record['id']]=$record['url'];?><form data-api="page-suggestions" data-output="page-suggestion-output"><input type="hidden" name="website_id" value="<?=$wid?>"><?php select_field('id','Crawled page',$pageChoices);?><button class="button">✧ Generate recommendations</button></form><pre id="page-suggestion-output" hidden></pre><form data-api="save-page-suggestions"><input type="hidden" name="website_id" value="<?=$wid?>"><?php select_field('id','Page',$pageChoices);?><label>Edit recommendations<textarea name="content" rows="8" required></textarea></label><button class="button secondary">Save for review</button></form><?php foreach(rows('SELECT r.content,r.source,p.url FROM page_recommendations r JOIN pages p ON p.id=r.page_id WHERE r.website_id=? ORDER BY r.id DESC LIMIT 10',[$wid]) as $rec):?><details class="issue"><summary><?=e($rec['url'])?> · <?=e($rec['source'])?></summary><pre><?=e($rec['content'])?></pre></details><?php endforeach;?></div>
